examples.template:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
    MonarchText(text = keyName, style = MonarchTextStyle.BodyStrong)
    MonarchText(text = "{{item.detail|raw}} · Last used $lastUsed", style = MonarchTextStyle.Caption)
    MonarchButton(
        text = {{trigger}},
        onClick = {
            typed = ""
            failure = null
            confirming = true
        },
        modifier = Modifier.semantics { contentDescription = "Revoke $keyName" },
        variant = MonarchButtonVariant.Danger,
    )
}
if (confirming) {
    MonarchDialog(
        onDismissRequest = { confirming = false },
        title = "Revoke API key?",
        icon = { MonarchIcon(SampleIcons.Warning, contentDescription = null, tint = MonarchTheme.colors.dangerStrong) },
        description = "A revoked key cannot be restored. Create a new key if you still need access.",
        dismissible = !revoking,
        actions = {
            MonarchButton(
                text = "Cancel",
                onClick = { confirming = false },
                size = MonarchButtonSize.Sm,
                enabled = !revoking,
            )
            MonarchButton(
                text = "Revoke key",
                onClick = {
                    revoking = true
                    scope.launch {
                        // The app's request. On failure set failure and keep the dialog open.
                        revoking = false
                        confirming = false
                    }
                },
                variant = MonarchButtonVariant.Danger,
                size = MonarchButtonSize.Sm,
                enabled = MonarchTypeToConfirmInputDefaults.matches(typed, keyName),
                loading = revoking,
            )
        },
    ) {
        Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3)) {
            MonarchCard {
                MonarchText(text = keyName, style = MonarchTextStyle.BodyStrong)
                MonarchText(text = "{{item.detail|raw}}", style = MonarchTextStyle.Caption)
                MonarchText(text = "Last used $lastUsed", style = MonarchTextStyle.Caption)
            }
            MonarchConsequenceList(
                items = listOf(
                    MonarchConsequence(MonarchConsequenceKind.Removed, "Apps and scripts using this key stop working immediately"),
                ),
                heading = "What happens",
            )
            MonarchTypeToConfirmInput(phrase = keyName, value = typed, onValueChange = { typed = it })
            failure?.let { MonarchInlineNotice(message = it, tone = MonarchTone.Danger) }
        }
    }
}

examples.setupTemplate:
val keyName = {{item.label}}
val scope = rememberCoroutineScope()
var confirming by rememberSaveable { mutableStateOf(true) }
var typed by remember { mutableStateOf("") }
var revoking by remember { mutableStateOf(false) }
var failure by remember { mutableStateOf<String?>(null) }
val now = remember { System.currentTimeMillis() }
val lastUsed = DateUtils.getRelativeTimeSpanString(now - {{item.lastUsedHoursAgo}} * DateUtils.HOUR_IN_MILLIS, now, DateUtils.MINUTE_IN_MILLIS)

